def find_minimal_edit(s_in, s_out):
    """Find the minimal edit between two strings"""
    # Simple approach: find first difference and determine what needs to change
    min_len = min(len(s_in), len(s_out))

    # Check prefix
    prefix_len = 0
    for i in range(min_len):
        if s_in[i] == s_out[i]:
            prefix_len += 1
        else:
            break

    # Check suffix
    suffix_len = 0
    for i in range(1, min_len + 1):
        if s_in[-i] == s_out[-i]:
            suffix_len += 1
        else:
            break

    # Determine what to replace
    if prefix_len + suffix_len >= len(s_in):
        # Complete replacement or insertion/deletion
        if len(s_in) < len(s_out):
            # Insertion case
            return (s_in[prefix_len:], s_out[prefix_len:], prefix_len)
        elif len(s_in) > len(s_out):
            # Deletion case  
            return (s_in[len(s_out):], "", len(s_out))
        else:
            # Full replacement
            return (s_in, s_out, 0)
    else:
        # Partial replacement
        old_part = s_in[prefix_len: len(s_in) - suffix_len]
        new_part = s_out[prefix_len: len(s_out) - suffix_len]
        return (old_part, new_part, prefix_len)

inputs = ['cey', 'fjz', 'kgivvj', 'vviuw', 'ye']
outputs = ['cdyj', 'fjz', 'kgivvj', 'vvivhw', 'd']

changed_pairs = [(0, 'cey', 'cdyj'), (3, 'vviuw', 'vvivhw'), (4, 'ye', 'd')]

for idx, inp, outp in changed_pairs:
    old_sub, new_sub, pos = find_minimal_edit(inp, outp)
    print(f"Pair {idx}: '{inp}' -> '{outp}'")
    print(f"  Old substring: '{old_sub}', New substring: '{new_sub}', Position: {pos}")

